import{_ as e,a as n,o as a,a4 as d}from"./chunks/framework.-FZumj2l.js";const b=JSON.parse('{"title":"Catalog Attribute Options — Create / Update / Delete (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-attribute-option-create","title":"Create Attribute Option","description":"Add a new option to a select/multiselect/checkbox attribute. The parent attribute is named by attributeId in the input. Returns the created option.","query":"mutation CreateAttributeOption($input: createAdminAttributeOptionInput!) {\\n  createAdminAttributeOption(input: $input) {\\n    adminAttributeOption {\\n      _id\\n      attributeId\\n      adminName\\n      sortOrder\\n      swatchValue\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"attributeId\\": 12,\\n    \\"adminName\\": \\"Green\\",\\n    \\"sortOrder\\": 2,\\n    \\"swatchValue\\": \\"#00FF00\\",\\n    \\"translations\\": {\\n      \\"en\\": { \\"label\\": \\"Green\\" },\\n      \\"fr\\": { \\"label\\": \\"Vert\\" }\\n    }\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminAttributeOption\\": {\\n      \\"adminAttributeOption\\": {\\n        \\"_id\\": 45,\\n        \\"attributeId\\": 12,\\n        \\"adminName\\": \\"Green\\",\\n        \\"sortOrder\\": 2,\\n        \\"swatchValue\\": \\"#00FF00\\"\\n      }\\n    }\\n  }\\n}\\n"},{"id":"admin-catalog-attribute-option-update","title":"Update Attribute Option","description":"Partial update of one option. Identify it with the option IRI plus attributeId and optionId. Returns the updated option.","query":"mutation UpdateAttributeOption($input: updateAdminAttributeOptionInput!) {\\n  updateAdminAttributeOption(input: $input) {\\n    adminAttributeOption {\\n      _id\\n      attributeId\\n      adminName\\n      sortOrder\\n      swatchValue\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/catalog/attributes/12/options/45\\",\\n    \\"attributeId\\": 12,\\n    \\"optionId\\": 45,\\n    \\"adminName\\": \\"Forest Green\\",\\n    \\"sortOrder\\": 1,\\n    \\"swatchValue\\": \\"#228B22\\",\\n    \\"translations\\": {\\n      \\"en\\": { \\"label\\": \\"Forest Green\\" },\\n      \\"fr\\": { \\"label\\": \\"Vert Forêt\\" }\\n    }\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"updateAdminAttributeOption\\": {\\n      \\"adminAttributeOption\\": {\\n        \\"_id\\": 45,\\n        \\"attributeId\\": 12,\\n        \\"adminName\\": \\"Forest Green\\",\\n        \\"sortOrder\\": 1,\\n        \\"swatchValue\\": \\"#228B22\\"\\n      }\\n    }\\n  }\\n}\\n"},{"id":"admin-catalog-attribute-option-delete","title":"Delete Attribute Option","description":"Delete one option, identified by its option IRI plus attributeId and optionId. Refused if products still reference the option. Returns the deleted option snapshot.","query":"mutation DeleteAttributeOption($input: deleteAdminAttributeOptionInput!) {\\n  deleteAdminAttributeOption(input: $input) {\\n    adminAttributeOption {\\n      _id\\n      attributeId\\n      adminName\\n      sortOrder\\n      swatchValue\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/catalog/attributes/12/options/45\\",\\n    \\"attributeId\\": 12,\\n    \\"optionId\\": 45\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminAttributeOption\\": {\\n      \\"adminAttributeOption\\": {\\n        \\"_id\\": 45,\\n        \\"attributeId\\": 12,\\n        \\"adminName\\": \\"Green\\",\\n        \\"sortOrder\\": 2,\\n        \\"swatchValue\\": \\"#00FF00\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/attributes/attribute-options.md","filePath":"api/graphql-api/admin/catalog/attributes/attribute-options.md","lastUpdated":1784902076000}'),i={name:"api/graphql-api/admin/catalog/attributes/attribute-options.md"};function o(r,t,p,u,c,s){return a(),n("div",null,t[0]||(t[0]=[d('<h1 id="catalog-attribute-options-—-create-update-delete-graphql" tabindex="-1">Catalog Attribute Options — Create / Update / Delete (GraphQL) <a class="header-anchor" href="#catalog-attribute-options-—-create-update-delete-graphql" aria-label="Permalink to &quot;Catalog Attribute Options — Create / Update / Delete (GraphQL)&quot;">​</a></h1><p>Options are the selectable values of a <code>select</code>, <code>multiselect</code>, or <code>checkbox</code> attribute (e.g. the Red / Green / Blue values of a &quot;Color&quot; attribute). They cannot be added to any other attribute type. Per-locale labels go under each option&#39;s <code>translations</code>. All three mutations return the option as <code>adminAttributeOption</code>; select its <code>_id</code> (the numeric option id) rather than <code>id</code>, since the option has no standalone detail route.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>See the <a href="/api/graphql-api/admin/catalog/attributes/">Attributes overview</a> for how attributes, options, and families fit together.</p></div><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>createAdminAttributeOption</code></td><td>Mutation</td><td>Add an option to a <code>select</code>/<code>multiselect</code>/<code>checkbox</code> attribute</td></tr><tr><td><code>updateAdminAttributeOption</code></td><td>Mutation</td><td>Partial update of an option</td></tr><tr><td><code>deleteAdminAttributeOption</code></td><td>Mutation</td><td>Remove an option</td></tr></tbody></table><p>Create takes the parent <code>attributeId: Int!</code> inside <code>input</code>. Update and delete identify the option with three input fields: the option IRI in <code>input.id</code> (<code>/api/admin/catalog/attributes/{attributeId}/options/{optionId}</code>) plus <code>attributeId: Int!</code> and <code>optionId: Int!</code>.</p><h2 id="input-—-create-update" tabindex="-1">Input — Create / Update <a class="header-anchor" href="#input-—-create-update" aria-label="Permalink to &quot;Input — Create / Update&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>attributeId</code></td><td><code>Int!</code></td><td>Parent attribute id (required on all three operations)</td></tr><tr><td><code>id</code></td><td><code>String</code></td><td>Option IRI — required on update and delete</td></tr><tr><td><code>optionId</code></td><td><code>Int</code></td><td>Option id — required on update and delete</td></tr><tr><td><code>adminName</code></td><td><code>String</code></td><td>Internal admin label (required on create)</td></tr><tr><td><code>sortOrder</code></td><td><code>Int</code></td><td>Display order</td></tr><tr><td><code>swatchValue</code></td><td><code>String</code></td><td>Hex color / image path / display text, depending on the parent attribute&#39;s swatch type</td></tr><tr><td><code>translations</code></td><td><code>JSON</code></td><td>Map of locale to <code>{ label }</code></td></tr></tbody></table><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Message</th></tr></thead><tbody><tr><td>Attribute is not <code>select</code>/<code>multiselect</code>/<code>checkbox</code></td><td><code>This attribute type does not support options.</code></td></tr><tr><td>Delete refused — option in use by products</td><td><code>This option is used by N product(s) and cannot be deleted.</code></td></tr><tr><td>Unknown id</td><td><code>Attribute option not found.</code></td></tr></tbody></table><p>All admin operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',11)]))}const h=e(i,[["render",o]]);export{b as __pageData,h as default};
